/* GNU C index helpers require integer constant expressions; invalid indices cannot alias another CSR. */
#ifndef __ASSEMBLER__
#define DASICS_INDEX_CHECK(index, count) \
	(0 * sizeof(struct { int dasics_index_must_be_constant_and_in_range : \
		(__builtin_constant_p(index) && ((index) | 0) >= 0 && (index) < (count)) ? 1 : -1; }))
#define DASICS_CSR_LIB_BOUND_LO(index) \
	(DASICS_CSR_LIB_BOUND_LO_0 + 2 * (index) + DASICS_INDEX_CHECK(index, DASICS_LIB_ENTRIES))
#define DASICS_CSR_LIB_BOUND_HI(index) \
	(DASICS_CSR_LIB_BOUND_HI_0 + 2 * (index) + DASICS_INDEX_CHECK(index, DASICS_LIB_ENTRIES))
#define DASICS_LIB_CFG_WRITE(index) \
	((DASICS_U64(1) << (DASICS_LIB_CFG_SLOT_BITS * (index) + DASICS_LIB_CFG_WRITE_BIT)) + DASICS_INDEX_CHECK(index, DASICS_LIB_ENTRIES))
#define DASICS_LIB_CFG_READ(index) \
	((DASICS_U64(1) << (DASICS_LIB_CFG_SLOT_BITS * (index) + DASICS_LIB_CFG_READ_BIT)) + DASICS_INDEX_CHECK(index, DASICS_LIB_ENTRIES))
#define DASICS_LIB_CFG_VALID(index) \
	((DASICS_U64(1) << (DASICS_LIB_CFG_SLOT_BITS * (index) + DASICS_LIB_CFG_VALID_BIT)) + DASICS_INDEX_CHECK(index, DASICS_LIB_ENTRIES))
#define DASICS_CSR_JUMP_BOUND_LO(index) \
	(DASICS_CSR_JUMP_BOUND_LO_0 + 2 * (index) + DASICS_INDEX_CHECK(index, DASICS_JUMP_ENTRIES))
#define DASICS_CSR_JUMP_BOUND_HI(index) \
	(DASICS_CSR_JUMP_BOUND_HI_0 + 2 * (index) + DASICS_INDEX_CHECK(index, DASICS_JUMP_ENTRIES))
#define DASICS_JUMP_CFG_VALID(index) \
	((DASICS_U64(1) << (DASICS_JUMP_CFG_SLOT_BITS * (index) + DASICS_JUMP_CFG_VALID_BIT)) + DASICS_INDEX_CHECK(index, DASICS_JUMP_ENTRIES))
#endif

